const defaults=[{name:'A little moment',duration:60},{name:'Find your rhythm',duration:180},{name:'Take your time',duration:300}];
let saved;try{saved=JSON.parse(localStorage.getItem('tap-presets'))}catch{};
const timers=defaults.map((d,i)=>{const s=saved?.[i];return {...(s&&typeof s.name==='string'&&Number.isInteger(s.duration)&&s.duration>0&&s.duration<=59999?{name:s.name.slice(0,24),duration:s.duration}:d),state:'ready',remaining:0,deadline:0}});
let sound=true,audio,editing=0;
try{sound=localStorage.getItem('tap-sound')!=='off'}catch{}
const $=s=>document.querySelector(s),editor=$('#editor');
const pencil='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path d="m5 19 1-4L16 5l3 3L9 18l-4 1Z"/></svg>';
$('#timers').innerHTML=timers.map((_,i)=>`<section class="timer" data-state="ready"><div class="progress"></div><div class="tile-top"><span class="tile-label"><span class="number">0${i+1}</span><span class="name"></span></span><button class="edit" aria-label="Edit timer ${i+1}">${pencil}</button></div><button class="timer-main"><span class="time"></span><span class="state"><span class="play-icon" aria-hidden="true">▶</span><span class="action">Tap to start</span></span></button><div class="tile-bottom"><span class="note">Your moment, on repeat.</span><button class="reset" hidden>Reset ↺</button></div></section>`).join('');
const tiles=[...document.querySelectorAll('.timer')];
function format(seconds){return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`}
function render(i){const t=timers[i],el=tiles[i],seconds=Math.ceil(t.state==='ready'?t.duration:t.remaining/1000);el.dataset.state=t.state;el.querySelector('.name').textContent=t.name;el.querySelector('.time').textContent=format(seconds);el.querySelector('.time').style.fontSize=seconds>=6000?'clamp(46px, 6.5vw, 110px)':'';const labels={ready:'Tap to start',running:'Tap to pause',paused:'Tap to resume',done:'Tap to go again'};el.querySelector('.action').textContent=labels[t.state];el.querySelector('.play-icon').textContent=t.state==='running'?'Ⅱ':t.state==='done'?'↻':'▶';el.querySelector('.timer-main').setAttribute('aria-label',`${t.name}, ${format(seconds)}. ${labels[t.state]}. Double tap to reset.`);el.querySelector('.edit').setAttribute('aria-label',`Edit ${t.name}`);el.querySelector('.reset').hidden=t.state==='ready'||t.state==='done';el.querySelector('.note').textContent=t.state==='done'?"Time’s up. Ready for another?":t.state==='ready'?'Your moment, on repeat.':`${format(t.duration)} timer`;el.querySelector('.progress').style.transform=`scaleY(${t.state==='ready'?0:1-t.remaining/(t.duration*1000)})`}
function unlockAudio(){try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume().catch(()=>{})}catch{}}
function ring(){if(!sound||!audio)return;try{[0,.22,.44].forEach((delay,i)=>{const oscillator=audio.createOscillator(),gain=audio.createGain(),at=audio.currentTime+delay;oscillator.type='sine';oscillator.frequency.value=[660,830,990][i];gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(.22,at+.015);gain.gain.exponentialRampToValueAtTime(.001,at+.6);oscillator.connect(gain);gain.connect(audio.destination);oscillator.start(at);oscillator.stop(at+.65)})}catch{}}
function finish(i){const t=timers[i];t.state='done';t.remaining=0;ring();render(i);$('#announcements').textContent=`${t.name} finished. Tap to start again.`;t.resetTimeout=setTimeout(()=>{if(t.state==='done')reset(i)},1000);}
function tick(){timers.forEach((t,i)=>{if(t.state!=='running')return;t.remaining=Math.max(0,t.deadline-Date.now());if(!t.remaining)finish(i);else render(i)})}
function toggle(i){unlockAudio();tick();const t=timers[i];clearTimeout(t.resetTimeout);if(t.state==='running'){t.state='paused'}else{if(t.state!=='paused')t.remaining=t.duration*1000;t.deadline=Date.now()+t.remaining;t.state='running'}render(i)}
function reset(i){clearTimeout(timers[i].resetTimeout);timers[i].state='ready';timers[i].remaining=timers[i].duration*1000;render(i)}
tiles.forEach((el,i)=>{let lastTap=-Infinity;el.querySelector('.timer-main').addEventListener('click',e=>{const now=performance.now();if(e.detail!==0&&now-lastTap<320){reset(i);lastTap=-Infinity}else{toggle(i);lastTap=e.detail===0?-Infinity:now}});el.querySelector('.reset').addEventListener('click',()=>reset(i));el.querySelector('.edit').addEventListener('click',()=>{editing=i;$('#timer-name').value=timers[i].name;$('#minutes').value=Math.floor(timers[i].duration/60);$('#seconds').value=timers[i].duration%60;$('#error').textContent='';editor.showModal()});render(i)});
$('#close-editor').onclick=()=>editor.close();editor.addEventListener('click',e=>{if(e.target===editor){const r=editor.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)editor.close()}});
$('#edit-form').onsubmit=e=>{e.preventDefault();const minutes=Number($('#minutes').value),seconds=Number($('#seconds').value),duration=minutes*60+seconds;if(!Number.isInteger(minutes)||!Number.isInteger(seconds)||minutes<0||minutes>999||seconds<0||seconds>59||duration<1){$('#error').textContent='Choose a duration of at least one second.';return}timers[editing].name=$('#timer-name').value.trim()||defaults[editing].name;timers[editing].duration=duration;reset(editing);try{localStorage.setItem('tap-presets',JSON.stringify(timers.map(({name,duration})=>({name,duration}))))}catch{}editor.close()};
function updateSound(){$('#sound').innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M12 5 7 9H4v6h3l5 4Z"/>${sound?'<path d="M17 9a5 5 0 0 1 0 6"/>':'<path d="m17 10 4 4m0-4-4 4"/>'}</svg>`;$('#sound').setAttribute('aria-pressed',String(sound));$('#sound').setAttribute('aria-label',`Sound ${sound?'on':'off'}`)}
$('#sound').onclick=()=>{sound=!sound;unlockAudio();updateSound();try{localStorage.setItem('tap-sound',sound?'on':'off')}catch{}};updateSound();
document.addEventListener('keydown',e=>{if(editor.open||e.repeat||e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(/^[123]$/.test(e.key)){e.preventDefault();toggle(Number(e.key)-1)}});
setInterval(tick,100);document.addEventListener('visibilitychange',tick);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'control_timer',description:'Start, pause, resume or reset one of the three repeat timers.',inputSchema:{type:'object',properties:{timer:{type:'integer',minimum:1,maximum:3},action:{type:'string',enum:['start','pause','resume','reset']}},required:['timer','action'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({timer,action})=>{if(!Number.isInteger(timer)||timer<1||timer>3||!['start','pause','resume','reset'].includes(action))throw Error('Invalid timer or action');const i=timer-1,t=timers[i];tick();if(action==='reset')reset(i);else if(action==='start'){reset(i);toggle(i)}else if((action==='pause'&&t.state==='running')||(action==='resume'&&t.state==='paused'))toggle(i);else throw Error('Action does not match timer state');return {timer,state:t.state,remainingSeconds:Math.ceil(t.remaining/1000)}}})).catch(()=>{})}catch{}}

// Localhost is a secure context; hosted installations require HTTPS.
if ('serviceWorker' in navigator && window.isSecureContext) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('./sw.js').catch(error => console.warn('Offline setup failed:', error));
  });
}
